import 'dart:convert';import 'dart:io';import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:flutter_secure_storage/flutter_secure_storage.dart';import 'package:flutter_test/flutter_test.dart';import 'package:integration_test/integration_test.dart';import 'package:mobile_shared/mobile_api.dart';import 'package:mobile_shared/bitpos_theme.dart';import 'package:bitpos_driver/payout_beneficiary_page.dart';
import 'package:http/http.dart' as http;import 'package:mobile_shared/settlement_beneficiary_mutation.dart';
class LostVerificationResponse extends http.BaseClient{
 final _delegate=http.Client();int dropped=0;
 @override Future<http.StreamedResponse> send(http.BaseRequest request)async{
  final response=await http.Response.fromStream(await _delegate.send(request));
  if(dropped==0&&request.url.path.contains('/payout-beneficiaries/')&&request.url.path.endsWith('/verify')&&response.statusCode==200){dropped++;throw http.ClientException('Synthetic response loss after actual verification COMMIT');}
  return http.StreamedResponse(Stream.value(response.bodyBytes),response.statusCode,headers:response.headers);
 }
 @override void close()=>_delegate.close();
}
