 final transport=LostVerificationResponse(),api=MobileApi(base:Uri.parse(const String.fromEnvironment('BITPOS_MOBILE_API')),fixture:true,client:transport);await api.restore();addTearDown(api.close);expect(api.signedIn,isTrue);
