 await tester.pumpWidget(MaterialApp(theme:BitPosTheme.light(),home:PayoutBeneficiaryPage(api:api,thai:false)));
 await visible(find.text('Create ownership challenge'));await tester.enterText(find.byType(TextField).at(0),const String.fromEnvironment('BITPOS_TEST_MERCHANT_ID'));await tester.enterText(find.byType(TextField).at(1),const String.fromEnvironment('BITPOS_TEST_DESTINATION'));
 await tester.ensureVisible(find.text('Create ownership challenge'));await tester.tap(find.text('Create ownership challenge'));await tester.pump();await visible(find.text('Copy exact signing message'));
 await tester.ensureVisible(find.text('Copy exact signing message'));await tester.tap(find.text('Copy exact signing message'));await tester.pump();
 final clipboard=await tester.runAsync(()=>Clipboard.getData(Clipboard.kTextPlain));expect(clipboard,isNotNull);final message=clipboard!.text!;expect(jsonDecode(message)[0],'BitPOS/SolanaDevnet/PayoutBeneficiaryOwnership/v1');debugPrint('BITPOS_BENEFICIARY088_CHALLENGE_VISIBLE');await tester.runAsync(()=>Future<void>.delayed(const Duration(seconds:2)));
 // Explicit external-wallet stand-in signs only exact stored challenge bytes.
 // No key/seed or signer package is present in the distributed app.
 final signed=await tester.runAsync(()async{final uri=Uri.parse(const String.fromEnvironment('BITPOS_TEST_EXTERNAL_SIGNER'));if(uri.host!='10.0.2.2'||uri.scheme!='http')throw StateError('Local external-signature fixture required');final client=HttpClient();try{final request=await client.postUrl(uri);request.headers.contentType=ContentType.text;request.write(message);final response=await request.close();if(response.statusCode!=200)throw StateError('External signature fixture refused');return utf8.decode(await response.fold<List<int>>([], (all,chunk)=>all..addAll(chunk)));}finally{client.close(force:true);}});
 await tester.enterText(find.byType(TextField).last,signed!);await tester.ensureVisible(find.text('Submit signature for server verification'));await tester.tap(find.text('Submit signature for server verification'));await tester.pump();
 // The outcome notice is above the long form, not below the signature field.
 await tester.drag(find.byType(ListView).last,const Offset(0,10000));await tester.pump();
 final unknown=find.text('Outcome may be unknown. Reload and retry the exact saved command; do not replace it.'),deadline=DateTime.now().add(const Duration(seconds:35));while(unknown.evaluate().isEmpty&&DateTime.now().isBefore(deadline)){await tester.pump(const Duration(milliseconds:100));}expect(unknown,findsOneWidget);expect(transport.dropped,1);
 final unresolved=await tester.runAsync(()=>api.pendingSettlementBeneficiary());expect(unresolved,isA<VerifySettlementBeneficiary>());final beneficiaryId=jsonDecode(message)[7] as String,originalSession=api.sessionScope!;
 await tester.runAsync(()=>api.logout());await tester.pump();expect(find.text('Session changed; private facts hidden.'),findsOneWidget);await tester.runAsync(()=>api.verifyOtp(const String.fromEnvironment('BITPOS_TEST_PHONE'),'123456'));expect(api.sessionScope!.accountId,originalSession.accountId);expect(api.sessionScope!.sessionId,isNot(originalSession.sessionId));
 await tester.pumpWidget(const SizedBox.shrink());await tester.pumpWidget(MaterialApp(theme:BitPosTheme.light(),home:PayoutBeneficiaryPage(api:api,thai:false)));await visible(find.text('VERIFIED · $beneficiaryId'));expect(await tester.runAsync(()=>api.pendingSettlementBeneficiary()),isNull);expect(api.signedIn,isTrue);expect(transport.dropped,1);await tester.ensureVisible(find.text('VERIFIED · $beneficiaryId'));await tester.tap(find.text('VERIFIED · $beneficiaryId'));await tester.pump();await visible(find.text('Server state: VERIFIED'));debugPrint('BITPOS_BENEFICIARY088_VERIFIED');await tester.runAsync(()=>Future<void>.delayed(const Duration(seconds:2)));
 await tester.runAsync(()=>api.logout());await tester.pump();expect(find.text('Session changed; private facts hidden.'),findsOneWidget);expect(find.byType(SelectableText),findsNothing);expect(find.byType(TextField),findsNothing);await Clipboard.setData(const ClipboardData(text:''));debugPrint('BITPOS_BENEFICIARY088_RETIRED');await tester.runAsync(()=>Future<void>.delayed(const Duration(seconds:2)));
